            aIngress = aIngress + RotL64(aOrbiterB, 57U);
            aIngress = TwistMix64::DiffuseB((aIngress + aScatter));
            //
            aWandererA = aWandererA ^ ((RotL64(aIngress, 37U) + RotL64(aOrbiterK, 18U)) + aOrbiterH);
            aWandererB = aWandererB + ((((RotL64(aCross, 14U) + RotL64(aOrbiterG, 41U)) + aOrbiterI) + RotL64(aCarry, 47U)) + aWUSaltA[(((511U - aIndex) + 33U)) & S_SALT1]);
            aWandererI = aWandererI ^ (((RotL64(aScatter, 53U) + aOrbiterD) + RotL64(aOrbiterB, 53U)) + aWUSaltH[(((511U - aIndex) + 5U)) & S_SALT1]);
            aWandererE = aWandererE + (((RotL64(aPrevious, 23U) + RotL64(aOrbiterK, 27U)) + aOrbiterG) + aWUSaltF[((aIndex + 475U)) & S_SALT1]);
            aWandererF = aWandererF ^ (((RotL64(aScatter, 29U) + aOrbiterD) + RotL64(aOrbiterA, 3U)) + aWUSaltD[((aIndex + 320U)) & S_SALT1]);
            aWandererG = aWandererG + ((RotL64(aCross, 41U) + RotL64(aOrbiterC, 58U)) + aOrbiterH);
            aWandererC = aWandererC ^ ((RotL64(aIngress, 57U) + aOrbiterC) + RotL64(aOrbiterG, 13U));
            aWandererK = aWandererK + (((RotL64(aPrevious, 10U) + aOrbiterF) + RotL64(aOrbiterC, 35U)) + RotL64(aCarry, 27U));
