            aOrbiterA = (aWandererI + RotL64(aPrevious, 51U)) + 0xA395B96DBF86789EULL;
            aOrbiterI = (aWandererJ + RotL64(aScatter, 23U)) + 0x909F045B39D86602ULL;
            aOrbiterF = (((aWandererG + RotL64(aCross, 47U)) + RotL64(aCarry, 51U)) + 0x5A1210FBEECDD3C2ULL) + aOASaltB[((aIndex + 267U)) & S_SALT1];
            aOrbiterD = ((aWandererA + RotL64(aIngress, 56U)) + 0x33EA0C7BFAAD4C04ULL) + aOASaltD[(((511U - aIndex) + 504U)) & S_SALT1];
            aOrbiterB = (aWandererE + RotL64(aCross, 35U)) + 0x3CBAAA6F127637EAULL;
            aOrbiterK = (((aWandererC + RotL64(aScatter, 29U)) + RotL64(aCarry, 23U)) + 0x8F820C20C8E63450ULL) + aOASaltC[(((511U - aIndex) + 311U)) & S_SALT1];
            aOrbiterH = (aWandererB + RotL64(aIngress, 11U)) + 0x1DE8783C0E487EEAULL;
            aOrbiterG = ((aWandererF + RotL64(aPrevious, 4U)) + RotL64(aCarry, 37U)) + 0xDDC6175365528512ULL;
            aOrbiterC = ((aWandererK + RotL64(aScatter, 41U)) + 0x609EBDEFD1317483ULL) + aOASaltH[(((511U - aIndex) + 124U)) & S_SALT1];
            //
            aOrbiterA = (aOrbiterA + aOrbiterI) + 0xE4D9246963E557CEULL;
            aOrbiterF = (aOrbiterF ^ aOrbiterA) ^ 0xB5FA0ACCB179A09CULL;
            aOrbiterF = RotL64((aOrbiterF * 0xE767CA301433AA1DULL), 13U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterA) + 0x11C3AF539D84E81AULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterD) ^ 0x7EEB5AC052D8A258ULL;
            aOrbiterB = RotL64((aOrbiterB * 0x647A69267E9E7761ULL), 51U);
            //
            aOrbiterI = ((aOrbiterI + aOrbiterD) + 0xCFAF12F15FC1456AULL) + aOUSaltF[(((511U - aIndex) + 65U)) & S_SALT1];
            aOrbiterK = (aOrbiterK ^ aOrbiterI) ^ 0x42CE1731DD4D3427ULL;
            aOrbiterK = RotL64((aOrbiterK * 0xE6D1ABB158422CA5ULL), 5U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterF) + 0x851AB6D63DC6577DULL;
            aOrbiterH = ((aOrbiterH ^ aOrbiterB) ^ 0xAEB1EE16AACD449AULL) ^ aOUSaltC[((aIndex + 431U)) & S_SALT1];
            aOrbiterH = RotL64((aOrbiterH * 0x09B0A770A3B8C0B9ULL), 57U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterH) + 0x49482145D31A8F59ULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterG) ^ 0x06D5BF7ED6125963ULL;
            aOrbiterD = RotL64((aOrbiterD * 0xD95A659E3EE2FD65ULL), 23U);
            //
            aOrbiterF = ((aOrbiterF + aOrbiterK) + 0xADAF14A06321E327ULL) + aOUSaltB[(((511U - aIndex) + 57U)) & S_SALT1];
            aOrbiterC = (aOrbiterC ^ aOrbiterF) ^ 0x39977CB556857986ULL;
            aOrbiterC = RotL64((aOrbiterC * 0x5F1F94823E0B1CAFULL), 39U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterB) + 0x37C95958BB1BADBFULL;
            aOrbiterG = ((aOrbiterG ^ aOrbiterK) ^ 0x594A6287E8878BC5ULL) ^ aOUSaltG[((aIndex + 183U)) & S_SALT1];
            aOrbiterG = RotL64((aOrbiterG * 0x7F7E43DC88E1E8F5ULL), 35U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterG) + 0x3B0DF4108F51862BULL;
            aOrbiterI = ((aOrbiterI ^ aOrbiterC) ^ 0xA42AC625929D2452ULL) ^ aOUSaltA[((aIndex + 35U)) & S_SALT1];
            aOrbiterI = RotL64((aOrbiterI * 0x386498EDB9F8A39DULL), 47U);
