            aOrbiterG = ((aWandererE + RotL64(aPrevious, 19U)) + RotL64(aCarry, 53U)) + 0x3C48EA21B72E8BCBULL;
            aOrbiterI = ((aWandererD + RotL64(aScatter, 29U)) + 0x6F020F4FD23CA116ULL) + aOASaltE[((aIndex + 137U)) & S_SALT1];
            aOrbiterA = ((aWandererK + RotL64(aCross, 13U)) + RotL64(aCarry, 11U)) + 0xAEB42F962CD25ADDULL;
            aOrbiterD = ((aWandererB + RotL64(aPrevious, 3U)) + 0xC4E3E42DB83A0352ULL) + aOASaltH[(((511U - aIndex) + 106U)) & S_SALT1];
            aOrbiterJ = (aWandererF + RotL64(aIngress, 60U)) + 0x71010A351A3E6E68ULL;
            aOrbiterF = ((aWandererC + RotL64(aScatter, 53U)) + 0x10DE4D2216D0CF83ULL) + aOASaltC[((aIndex + 305U)) & S_SALT1];
            //
            aOrbiterH = ((aOrbiterH + aOrbiterG) + 0x4C4351060D2459B7ULL) + aOUSaltF[((aIndex + 164U)) & S_SALT1];
            aOrbiterI = (aOrbiterI ^ aOrbiterH) ^ 0x6A91A4331CADF98BULL;
            aOrbiterI = RotL64((aOrbiterI * 0x3DBF504A9DD9FD81ULL), 43U);
            //
            aOrbiterA = ((aOrbiterA + aOrbiterH) + 0x1893646F462FA957ULL) + aOUSaltH[(((511U - aIndex) + 483U)) & S_SALT1];
            aOrbiterD = (aOrbiterD ^ aOrbiterA) ^ 0x169AF37BED164B10ULL;
            aOrbiterD = RotL64((aOrbiterD * 0xE37C2A26224BC8F9ULL), 5U);
            //
            aOrbiterD = ((aOrbiterD + aOrbiterI) + 0x2C857B24BD6DA8D1ULL) + aOUSaltE[((aIndex + 215U)) & S_SALT1];
            aOrbiterJ = (aOrbiterJ ^ aOrbiterD) ^ 0x69FA8719305AA2C7ULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0xF1E7D56F1C85321DULL), 11U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterD) + 0x12BEDC3A63036702ULL;
