            aOrbiterH = ((aOrbiterH ^ aOrbiterJ) ^ 0x279A075391BCFB5AULL) ^ aOUSaltA[(((511U - aIndex) + 361U)) & S_SALT1];
            aOrbiterH = RotL64((aOrbiterH * 0x5CA23BEE4D23DD31ULL), 29U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterJ) + 0xCAED16931B121BD0ULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterG) ^ 0x68FDE682B46C25ACULL;
            aOrbiterA = RotL64((aOrbiterA * 0xB6F9CF9143DA66F5ULL), 35U);
            //
            aOrbiterI = ((aOrbiterI + aOrbiterA) + 0x03C71D485EC3F871ULL) + aOUSaltC[(((511U - aIndex) + 132U)) & S_SALT1];
