            aScatter = TwistMix64::DiffuseA((aScatter ^ aTwistDomainWordScatter));
            //
            aOrbiterC = ((aWandererH + RotL64(aCross, 19U)) + RotL64(aCarry, 5U)) + 0x6AA99143A8C3AC9EULL;
            aOrbiterG = ((aWandererA + RotL64(aIngress, 21U)) + 0x4448E5B37AB657BAULL) + aOASaltA[(((511U - aIndex) + 32U)) & S_SALT1];
