            //
            aOrbiterG = ((aWandererE + RotL64(aCross, 48U)) + 0xB27AA2B17808716DULL) + aOASaltD[((aIndex + 453U)) & S_SALT1];
            aOrbiterH = ((aWandererJ + RotL64(aIngress, 39U)) + 0xAD11097502E3D70AULL) + aOASaltB[(((511U - aIndex) + 467U)) & S_SALT1];
