            aOrbiterD = ((aWandererD + RotL64(aPrevious, 41U)) + RotL64(aCarry, 57U)) + 0x275D2C7D4D9A2304ULL;
            aOrbiterF = (((aWandererE + RotL64(aScatter, 11U)) + RotL64(aCarry, 23U)) + 0x02EB3A79F0B7EA11ULL) + aOASaltD[(((511U - aIndex) + 290U)) & S_SALT1];
