            aWandererG = aWandererG ^ ((RotL64(aIngress, 11U) + aOrbiterG) + RotL64(aOrbiterF, 35U));
            aWandererH = aWandererH + (((RotL64(aScatter, 21U) + RotL64(aOrbiterC, 48U)) + aOrbiterH) + aWUSaltD[(((511U - aIndex) + 336U)) & S_SALT1]);
            aWandererD = aWandererD ^ ((RotL64(aPrevious, 39U) + RotL64(aOrbiterC, 37U)) + aOrbiterK);
