            //
            aOrbiterI = (aWandererF + RotL64(aCross, 27U)) + 0x6BF024C754DF7DAEULL;
            aOrbiterK = ((aWandererC + RotL64(aIngress, 35U)) + 0x91AD5139E59D4373ULL) + aOASaltC[((aIndex + 330U)) & S_SALT1];
            aOrbiterC = (((aWandererK + RotL64(aPrevious, 51U)) + RotL64(aCarry, 39U)) + 0x6031DDB27CE1D93FULL) + aOASaltD[((aIndex + 72U)) & S_SALT1];
