            aOrbiterJ = ((aWandererH + RotL64(aIngress, 13U)) + 0x5C6075F08A70E714ULL) + aOASaltH[(((511U - aIndex) + 505U)) & S_SALT1];
            aOrbiterG = (aWandererI + RotL64(aPrevious, 4U)) + 0xEC3CE4DC1AD9B1D6ULL;
            aOrbiterE = (((aWandererD + RotL64(aCross, 41U)) + RotL64(aCarry, 53U)) + 0x29F75319511942B8ULL) + aOASaltF[(((511U - aIndex) + 89U)) & S_SALT1];
