            //
            aOrbiterJ = (aOrbiterJ + aOrbiterC) + 0x677083AA9C296D1EULL;
            aOrbiterE = ((aOrbiterE ^ aOrbiterJ) ^ 0x4EE0289F82CD17B8ULL) ^ aOUSaltA[(((511U - aIndex) + 457U)) & S_SALT1];
            aOrbiterE = RotL64((aOrbiterE * 0xC8DC0FD168582FDBULL), 3U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterA) + 0x1606CF7C640BC734ULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterE) ^ 0xD61C17D31622E694ULL;
            aOrbiterK = RotL64((aOrbiterK * 0xBBB0AEF884966C49ULL), 21U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterE) + 0x1D8661C4C3DB4DDEULL;
            aOrbiterI = ((aOrbiterI ^ aOrbiterG) ^ 0x7319D479EF7D7F59ULL) ^ aOUSaltC[((aIndex + 41U)) & S_SALT1];
            aOrbiterI = RotL64((aOrbiterI * 0x7EF023DA25EBE97FULL), 57U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterG) + 0x1E66C92B5D504C3DULL;
