            aCross = TwistMix64::DiffuseC((aCross ^ aKeyRotateBDomainWordCross));
            //
            aScatter = (RotL64(aCarry, 34U) ^ RotL64(aPrevious, 19U)) + (RotL64(aIngress, 3U) ^ RotL64(aCross, 47U));
            aScatter = TwistMix64::DiffuseB((aScatter ^ aKeyRotateBDomainWordScatter));
            //
            aOrbiterD = ((aWandererI + RotL64(aPrevious, 35U)) + 0xF6FA0ADC6F908C7CULL) + aOASaltC[(((511U - aIndex) + 156U)) & S_SALT1];
            aOrbiterE = ((aWandererG + RotL64(aCross, 5U)) + RotL64(aCarry, 5U)) + 0x97890AD55E2A24F2ULL;
            aOrbiterG = ((aWandererC + RotL64(aScatter, 47U)) + RotL64(aCarry, 41U)) + 0x69528C799B482E74ULL;
            aOrbiterB = ((aWandererD + RotL64(aIngress, 13U)) + 0x9C1423777ACE5826ULL) + aOASaltB[((aIndex + 194U)) & S_SALT1];
            aOrbiterA = (aWandererK + RotL64(aCross, 41U)) + 0x67287E416EFCE47DULL;
            aOrbiterJ = ((aWandererE + RotL64(aPrevious, 19U)) + 0xC74BE90FD0F5341FULL) + aOASaltA[(((511U - aIndex) + 375U)) & S_SALT1];
